  insert into public.academy_corriges (question_id, bonne_reponse, explication) values (v_q, 1, $academy_seed$Lorsqu'un bénéficiaire a accepté le bénéfice du contrat, le souscripteur ne peut plus modifier la clause, ni racheter, ni demander une avance sans son accord. Vérifier ce point avant tout conseil de rachat ou de modification. Voir la leçon 3.$academy_seed$);
  insert into public.academy_questions (version_id, lecon_id, cle, type, competence, enonce, choix, difficulte)
